date,spc1.date,spc2.date)::date) = amazon_comm.amazon_month and upper(trim(coalesce(pli.pre_FINAL_Mapped_Marketplace,spc.channel,spc1.channel,spc2.channel))) = \'AMAZON\' and lower(pli.type) = \'sales\' left join ( SELECT \"Order Date\"::date as flipkart_Date, \'FLIPKART\' as flipkart_commisionFLag, sum(abs(\"Total Expenses (Breakup)\":\"Commission Fee\"::NUMBER) + abs(\"Total Expenses (Breakup)\":\"Collection Fee\"::NUMBER) + abs(\"Total Expenses (Breakup)\":\"Fixed Fee\"::NUMBER) + abs(\"Total Expenses (Breakup)\":\"No Cost Emi Fee Reimbursement(Rs.)\"::NUMBER)) AS Flipkart_Commission from sleepycat_db.maplemonk.flipkart_sleepycat_profit_and_loss_sales group by 1 limit 0 )flipkart_comm on coalesce(pre_date,spc.date,spc1.date,spc2.date)::date = flipkart_comm.flipkart_Date and upper(trim(coalesce(pli.pre_FINAL_Mapped_Marketplace,spc.channel,spc1.channel,spc2.channel))) = \'FLIPKART\' and lower(pli.type) = \'sales\' left join ( SELECT LAST_DAY(TO_DATE(DATE, \'DD-MM-YYYY\')) AS DATE, TRY_TO_NUMBER(SPLIT_PART(PRICE, \'-\', 1)) AS START_PRICE, TRY_TO_NUMBER(SPLIT_PART(PRICE, \'-\', 2)) AS END_PRICE, \'FLIPKART\' as flipkart_commisionFLag_sub, upper(subcategory_contains) as SubCategory_Contains, REPLACE(COMMISSION, \'%\', \'\')::NUMBER/100 AS FLIPKART_COMMISSION_sub FROM sleepycat_db.maplemonk.sleepycat_db_marketplace_commissions_flipkart where ifnull(REPLACE(COMMISSION, \'%\', \'\')::NUMBER,0) > 0 and subcategory_contains is not null QUALIFY ROW_NUMBER() over(partition by DATE,START_PRICE,END_PRICE,SubCategory_Contains order by 1) = 1 )flipkart_comm_subCategory on last_day(coalesce(pre_date,spc.date,spc1.date,spc2.date)::date) = last_day(flipkart_comm_subCategory.DATE) and upper(trim(coalesce(pli.pre_FINAL_Mapped_Marketplace,spc.channel,spc1.channel,spc2.channel))) = \'FLIPKART\' and ifnull(selling_price,0) >= flipkart_comm_subCategory.START_PRICE and ifnull(selling_price,0) <= flipkart_comm_subCategory.END_PRICE and upper(trim(coalesce(pli.Pre_product_sub_category,spc.subcategory))) like (\'%\' || upper(flipkart_comm_subCategory.SubCategory_Contains) || \'%\') and lower(pli.type) = \'sales\' left join ( SELECT LAST_DAY(TO_DATE(DATE, \'DD-MM-YYYY\')) AS DATE, TRY_TO_NUMBER(SPLIT_PART(PRICE, \'-\', 1)) AS START_PRICE, TRY_TO_NUMBER(SPLIT_PART(PRICE, \'-\', 2)) AS END_PRICE, \'FLIPKART\' as flipkart_commisionFLag1, upper(CATEGORY) Category, REPLACE(COMMISSION, \'%\', \'\')::NUMBER/100 AS FLIPKART_COMMISSION1 FROM sleepycat_db.maplemonk.sleepycat_db_marketplace_commissions_flipkart where ifnull(REPLACE(COMMISSION, \'%\', \'\')::NUMBER,0) > 0 and subcategory_contains is null QUALIFY ROW_NUMBER() over(partition by DATE,START_PRICE,END_PRICE,Category order by 1) = 1 )flipkart_comm1 on last_day(coalesce(pre_date,spc.date,spc1.date,spc2.date)::date) = last_day(flipkart_comm1.DATE) and upper(trim(coalesce(pli.pre_FINAL_Mapped_Marketplace,spc.channel,spc1.channel,spc2.channel))) = \'FLIPKART\' and ifnull(selling_price,0) >= flipkart_comm1.START_PRICE and ifnull(selling_price,0) <= flipkart_comm1.END_PRICE and upper(trim(coalesce(pli.Pre_PRODUCT_CATEGORY,spc.category,spc1.category))) = upper(flipkart_comm1.Category) and lower(pli.type) = \'sales\' left join ( SELECT LAST_DAY(TO_DATE(START_DATE, \'YYYY-MM-DD\')) AS DATE, TRY_TO_NUMBER(SPLIT_PART(PRICE, \'-\', 1)) AS START_PRICE, TRY_TO_NUMBER(SPLIT_PART(PRICE, \'-\', 2)) AS END_PRICE, \'FLIPKART\' as flipkart_commisionFLag2, upper(CATEGORY) Category, upper(subcateory_contains) SubCategory_Contains, REPLACE(COMMISSION, \'%\', \'\')::NUMBER AS FIXED_FEE FROM sleepycat_db.maplemonk.sleepycat_db_marketplace_commissions_fflipkart_fixed_rate where ifnull(REPLACE(COMMISSION, \'%\', \'\')::NUMBER,0) > 0 and subcateory_contains is not null QUALIFY ROW_NUMBER() over(partition by START_DATE,START_PRICE,END_PRICE,SubCategory_Contains,Category order by 1) = 1 )flipkart_fixed_sub on last_day(coalesce(pre_date,spc.date,spc1.date,spc2.date)::date) = last_day(flipkart_fixed_sub.DATE) and upper(trim(coalesce(pli.pre_FINAL_Mapped_Marketplace,spc.channel,spc1.channel,spc2.channel))) = \'FLIPKART\' and ifnull(selling_price,0) >= flipkart_fixed_sub.START_PRICE and ifnull(selling_price,0) <= flipkart_fixed_sub.END_PRICE and upper(trim(coalesce(pli.Pre_product_sub_category,spc.subcategory))) like (\'%\' || upper(flipkart_fixed_sub.SubCategory_Contains) || \'%\') and lower(pli.type) = \'sales\' left join ( SELECT LAST_DAY(TO_DATE(START_DATE, \'YYYY-MM-DD\')) AS DATE, TRY_TO_NUMBER(SPLIT_PART(PRICE, \'-\', 1)) AS START_PRICE, TRY_TO_NUMBER(SPLIT_PART(PRICE, \'-\', 2)) AS END_PRICE, \'FLIPKART\' as flipkart_commisionFLag2, upper(CATEGORY) Category, REPLACE(COMMISSION, \'%\', \'\')::NUMBER AS FIXED_FEE FROM sleepycat_db.maplemonk.sleepycat_db_marketplace_commissions_fflipkart_fixed_rate where ifnull(REPLACE(COMMISSION, \'%\', \'\')::NUMBER,0) > 0 and subcateory_contains is null QUALIFY ROW_NUMBER() over(partition by START_DATE,START_PRICE,END_PRICE,Category order by 1) = 1 )flipkart_comm2 on last_day(coalesce(pre_date,spc.date,spc1.date,spc2.date)::date) = last_day(flipkart_comm2.DATE) and upper(trim(coalesce(pli.pre_FINAL_Mapped_Marketplace,spc.channel,spc1.channel,spc2.channel))) = \'FLIPKART\' and ifnull(selling_price,0) >= flipkart_comm2.START_PRICE and ifnull(selling_price,0) <= flipkart_comm2.END_PRICE and upper(trim(coalesce(pli.Pre_PRODUCT_CATEGORY,spc.category,spc1.category))) = upper(flipkart_comm2.Category) and lower(pli.type) = \'sales\' left join ( SELECT TO_DATE(START_DATE, \'DD-MM-YYYY\') AS START_DATE, TO_DATE(END_DATE, \'DD-MM-YYYY\') AS END_DATE, \'AMAZON\' as amzon_commisionFLag1, TRY_TO_NUMBER(TRIM(SPLIT_PART(PRICE, \'-\', 1))) AS START_PRICE, TRY_TO_NUMBER(TRIM(SPLIT_PART(PRICE, \'-\', 2))) AS END_PRICE, UPPER(CATEGORY) AS CATEGORY, TRY_TO_NUMBER(REPLACE(COMMISSION, \'%\', \'\')) / 100 AS COMMISSION FROM sleepycat_db.maplemonk.sleepycat_db_amazon_commissions where ifnull(TRY_TO_NUMBER(REPLACE(COMMISSION, \'%\', \'\')),0) > 0 QUALIFY ROW_NUMBER() OVER (PARTITION BY TO_DATE(START_DATE, \'DD-MM-YYYY\'),TO_DATE(END_DATE, \'DD-MM-YYYY\'), TRY_TO_NUMBER(TRIM(SPLIT_PART(PRICE, \'-\', 1))), TRY_TO_NUMBER(TRIM(SPLIT_PART(PRICE, \'-\', 2))),UPPER(CATEGORY) ORDER BY TO_DATE(START_DATE, \'DD-MM-YYYY\')) = 1 )Amazon_comm1 on last_day(coalesce(pre_date,spc.date,spc1.date,spc2.date)::date) >= last_day(Amazon_comm1.START_DATE) and last_day(coalesce(pre_date,spc.date,spc1.date,spc2.date)::date) <= last_day(Amazon_comm1.END_DATE) and upper(trim(coalesce(pli.pre_FINAL_Mapped_Marketplace,spc.channel,spc1.channel,spc2.channel))) = \'AMAZON\' and ifnull(selling_price,0) >= Amazon_comm1.START_PRICE and ifnull(selling_price,0) <= Amazon_comm1.END_PRICE and (case when upper(trim(coalesce(pli.Pre_PRODUCT_CATEGORY,spc.category,spc1.category))) in (\'MATTRESS\',\'BEDDING\',\'BLANKETS\',\'COVERS\') then upper(trim(coalesce(pli.Pre_PRODUCT_CATEGORY,spc.category,spc1.category))) else \'OTHERS\' end) = upper(Amazon_comm1.Category) and lower(pli.type) = \'sales\' LEFT JOIN ( SELECT TO_DATE(START_DATE, \'YYYY-MM-DD\') AS START_DATE, TO_DATE(END_DATE, \'YYYY-MM-DD\') AS END_DATE, upper(trim(MarketPlace)) MarketPlace, UPPER(CATEGORY) AS CATEGORY, TRY_TO_NUMBER(REPLACE(COMMISSION, \'%\', \'\')) / 100 AS COMMISSION FROM sleepycat_db.maplemonk.sleepycat_db_sales_day_marketplace_commisions where ifnull(TRY_TO_NUMBER(REPLACE(COMMISSION, \'%\', \'\')),0) > 0 QUALIFY ROW_NUMBER() OVER (PARTITION BY TO_DATE(START_DATE, \'YYYY-MM-DD\'),TO_DATE(END_DATE, \'YYYY-MM-DD\'),upper(trim(MarketPlace)),UPPER(CATEGORY) ORDER BY 1) = 1 )marketplace_Com_fl_am on (coalesce(pre_date,spc.date,spc1.date,spc2.date)::date) >= (marketplace_Com_fl_am.START_DATE) and (coalesce(pre_date,spc.date,spc1.date,spc2.date)::date) <= (marketplace_Com_fl_am.END_DATE) and upper(trim(coalesce(pli.pre_FINAL_Mapped_Marketplace,spc.channel,spc1.channel,spc2.channel))) = upper(trim(marketplace_Com_fl_am.MarketPlace)) and (case when upper(trim(coalesce(pli.Pre_PRODUCT_CATEGORY,spc.category,spc1.category))) in (\'MATTRESS\',\'BEDDING\',\'BLANKETS\',\'COVERS\') then upper(trim(coalesce(pli.Pre_PRODUCT_CATEGORY,spc.category,spc1.category))) else \'OTHER\' end) = upper(marketplace_Com_fl_am.Category) and lower(pli.type) = \'sales\' ;",
